single_render_attempt.command_verbatim:
$ErrorActionPreference='Stop'
$node='C:\Program Files\nodejs\node.exe'
$src='design/career-world/concepts/tracer/contextforge-footprint-axis-guide-r2.svg'
$dst='design/career-world/concepts/tracer/contextforge-footprint-axis-guide-r2.png'
if(Test-Path -LiteralPath $dst){throw 'FINAL_PNG_ALREADY_EXISTS'}
$script=@'
const fs=require("fs");
const sharp=require("sharp");
const src=process.argv[1];
const dst=process.argv[2];
if(fs.existsSync(dst)){throw new Error("FINAL_PNG_ALREADY_EXISTS");}
sharp(src,{density:72,animated:false,failOn:"error",sequentialRead:true})
  .flatten({background:"#080B10"})
  .removeAlpha()
  .toColourspace("srgb")
  .png({compressionLevel:9,adaptiveFiltering:false,palette:false,effort:10,force:true})
  .toFile(dst)
  .then(function(info){
    if(info.format!=="png"||info.width!==1536||info.height!==1024||info.channels!==3){
      console.error(JSON.stringify({status:"NONCOMPLIANT_SINGLE_RENDER",info:info}));
      process.exitCode=2;
      return;
    }
    console.log(JSON.stringify({status:"SINGLE_RENDER_COMPLETED",info:info}));
  })
  .catch(function(error){
    console.error(JSON.stringify({status:"SINGLE_RENDER_FAILED",error:error.message}));
    process.exitCode=1;
  });
'@
& $node -e $script $src $dst
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE}
